from typing import Any


def json_pointer(doc: Any, pointer: str) -> Any:
    if not isinstance(pointer, str):
        raise ValueError("Pointer must be a string.")
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("Non-empty pointer must start with '/'.")

    current = doc
    for raw_segment in pointer[1:].split("/"):
        # Validate escape sequences: '~' must be followed by '0' or '1'
        i = 0
        while i < len(raw_segment):
            if raw_segment[i] == "~":
                if i + 1 >= len(raw_segment) or raw_segment[i + 1] not in "01":
                    raise ValueError(f"Invalid escape sequence in segment: {raw_segment!r}")
                i += 2
            else:
                i += 1

        # Decode '~1' before '~0' per RFC 6901 Section 4
        segment = raw_segment.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            if segment not in current:
                raise ValueError(f"Key '{segment}' not found.")
            current = current[segment]
        elif isinstance(current, list):
            if not segment or any(c < "0" or c > "9" for c in segment):
                raise ValueError(f"Invalid array index: '{segment}'.")
            if len(segment) > 1 and segment[0] == "0":
                raise ValueError(f"Invalid array index (leading zero): '{segment}'.")
            index = int(segment)
            if index >= len(current):
                raise ValueError(f"Index {index} out of range.")
            current = current[index]
        else:
            raise ValueError(f"Cannot index into type {type(current).__name__}.")

    return current
